package com.company.skillplatform.bundle.application;
import com.company.skillplatform.audit.application.DownloadAuditService;import com.company.skillplatform.bundle.infrastructure.repository.SkillBundleRepository;import com.company.skillplatform.common.application.BusinessException;import com.company.skillplatform.common.logging.LogContext;import com.company.skillplatform.storage.domain.ObjectStoragePort;import java.io.*;import org.springframework.core.io.ByteArrayResource;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class BundleDownloadService{private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(BundleDownloadService.class);private final SkillBundleRepository bundles;private final ObjectStoragePort storage;private final DownloadAuditService audit;public BundleDownloadService(SkillBundleRepository b,ObjectStoragePort s,DownloadAuditService a){bundles=b;storage=s;audit=a;}@PreAuthorize("hasAuthority('skill:download')")@Transactional(readOnly=true)public ResponseEntity<ByteArrayResource> download(Long id,Long userId){var b=bundles.findByIdAndCreatedById(id,userId).orElseThrow(()->{log.warn("event=bundle.download.denied requestId={} actorId={} bundleId={} errorCode={}",LogContext.requestId(),userId,id,"BUNDLE_NOT_FOUND");return new BusinessException("BUNDLE_NOT_FOUND","Bundle not found",HttpStatus.NOT_FOUND);});if(!"AVAILABLE".equals(b.getStatus())){log.warn("event=bundle.download.denied requestId={} actorId={} bundleId={} status={} errorCode={}",LogContext.requestId(),userId,id,b.getStatus(),"BUNDLE_NOT_AVAILABLE");throw new BusinessException("BUNDLE_NOT_AVAILABLE","Bundle is not available",HttpStatus.NOT_FOUND);}try(InputStream in=storage.get(b.getObjectKey())){byte[] bytes=in.readAllBytes();audit.record(userId,null,id,b.getObjectKey());log.info("event=bundle.download.succeeded requestId={} actorId={} bundleId={} bundleKey={} platform={} osType={} sizeBytes={}",LogContext.requestId(),userId,id,b.getBundleKey(),b.getPlatform().getPlatformKey(),b.getOsType(),bytes.length);return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).contentLength(bytes.length).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+b.getFileName()).body(new ByteArrayResource(bytes));}catch(IOException e){log.error("event=bundle.download.failed requestId={} actorId={} bundleId={} errorCode={}",LogContext.requestId(),userId,id,"BUNDLE_READ_FAILED",e);throw new BusinessException("BUNDLE_READ_FAILED","Unable to read bundle",HttpStatus.BAD_GATEWAY);}}}
